/* preview wave 3 AI — build-in-public feed from data/ai/shipped.json (generated by tools/ai/build_shipped.py from real records). */
import { esc } from './core.js';
const B = (window.MM_AI_CONFIG || {}).base || '/';
let P = null;
export const data = () => P || (P = fetch(B + 'data/ai/shipped.json').then(r => r.json()));
const M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
export function when(s) {
  if (!s) return 'Date not recorded in the source';
  const [dt, tm] = s.split('T'); const [y, m, d] = dt.split('-'); return `${+d} ${M[+m - 1]} ${y}` + (tm ? `, ${tm} SAST` : '');
}
function item(e) {
  return `<article class="mm-fe" data-project="${esc(e.project)}"><time${e.date ? ` datetime="${esc(e.date)}${e.date.length > 10 ? ':00+02:00' : ''}"` : ''}>${when(e.date)}</time>
    <h4>${e.link ? `<a href="${esc(e.link)}" style="color:inherit">${esc(e.title)}</a>` : esc(e.title)}</h4><p>${esc(e.summary)}</p>
    <div class="tags"><span class="p">${esc(e.project)}</span>${(e.tests || []).map(t => `<span class="t">${esc(t)} passed</span>`).join('')}<span title="Source record">${esc(e.source)}</span></div></article>`;
}
export async function mini(host, n = 3) {
  if (!host) return; const D = await data();
  host.innerHTML = '<p class="mm-kick" style="margin:4px 0 2px">Latest shipped</p>' + D.entries.filter(e => e.date).slice(0, n)
    .map(e => `<a href="${B}ai/#feed"><time>${when(e.date)} · ${esc(e.project)}</time>${esc(e.title)}${(e.tests || []).length ? ' · ' + esc(e.tests[0]) : ''}</a>`).join('');
}
export async function full(host) {
  const D = await data(); const projects = [...new Set(D.entries.map(e => e.project))];
  host.innerHTML = `<div class="mm-filters" role="group" aria-label="Filter by project"><button type="button" aria-pressed="true" data-f="">All (${D.entries.length})</button>${projects.map(p => `<button type="button" aria-pressed="false" data-f="${esc(p)}">${esc(p)}</button>`).join('')}</div>
    <div class="mm-feed" data-mm-feed>${D.entries.map(item).join('')}</div><p class="mm-note" style="margin-top:14px">${esc(D.note)} Generated ${esc(D.generated)}.</p>`;
  host.querySelector('.mm-filters').addEventListener('click', e => {
    const b = e.target.closest('[data-f]'); if (!b) return; host.querySelectorAll('[data-f]').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
    host.querySelectorAll('.mm-fe').forEach(a => { a.hidden = !!b.dataset.f && a.dataset.project !== b.dataset.f; });
  });
}
